pub fn add(self, rhs: CM31) -> CM31 {
        CM31 {
            a: self.a.add(rhs.a),
            b: self.b.add(rhs.b),
        }
    }

pub fn sub(self, rhs: CM31) -> CM31 {
        CM31 {
            a: self.a.sub(rhs.a),
            b: self.b.sub(rhs.b),
        }
    }

pub fn mul(self, rhs: CM31) -> CM31 {
        let m0 = self.a.mul(rhs.a);
        let m1 = self.b.mul(rhs.b);
        // Both unreduced sums are below `2P < 2^32`, so their product fits
        // in u64. Reducing after the product is identical to first reducing
        // each sum modulo P, and removes two canonical-add branches from
        // every CM31 multiplication.
        let m2 = M31::reduce_u64(
            (u64::from(self.a.0) + u64::from(self.b.0)) * (u64::from(rhs.a.0) + u64::from(rhs.b.0)),
        );
        CM31 {
            a: m0.sub(m1),
            b: m2.sub(m0).sub(m1),
        }
    }

pub fn add(self, rhs: QM31) -> QM31 {

        QM31 {
            c0: self.c0.add(rhs.c0),
            c1: self.c1.add(rhs.c1),
        }
    }

pub fn sub(self, rhs: QM31) -> QM31 {

        QM31 {
            c0: self.c0.sub(rhs.c0),
            c1: self.c1.sub(rhs.c1),
        }
    }

pub fn mul(self, rhs: QM31) -> QM31 {

        let m0 = self.c0.mul(rhs.c0);
        let m1 = self.c1.mul(rhs.c1);
        let m2 = self.c0.add(self.c1).mul(rhs.c0.add(rhs.c1));
        QM31 {
            c0: m0.add(mul_by_r(m1)),
            c1: m2.sub(m0).sub(m1),
        }
    }

fn mul_by_r(x: CM31) -> CM31 {
    // (2 + i)(a + bi) = (2a - b) + (a + 2b) i
    CM31 {
        a: x.a.double().sub(x.b),
        b: x.a.add(x.b.double()),
    }
}

pub fn mul(self, rhs: M31) -> M31 {

        M31(reduce_u64(self.0 as u64 * rhs.0 as u64))
    }

pub fn double(self) -> M31 {
        self.add(self)
    }

pub fn reduce_u64(value: u64) -> M31 {
        M31(reduce_u64(value))
    }

pub fn subtract_p(x: u32) -> u32 {
    let mask = 0u32.wrapping_sub((x >= P) as u32);
    x.wrapping_sub(P & mask)
}

pub fn reduce64(x: u64) -> u32 {
    let x = (x & P as u64) + (x >> 31);
    let x = (x & P as u64) + (x >> 31);
    subtract_p(x as u32)
}

pub fn add(a: u32, b: u32) -> u32 {
    subtract_p(a.wrapping_add(b))
}

pub fn sub(a: u32, b: u32) -> u32 {
    subtract_p(a.wrapping_add(P).wrapping_sub(b))
}

pub const ZERO: Self = Self {
        c0: QM31::ZERO,
        c1: QM31::ZERO,
    }

pub const ONE: Self = Self {
        c0: QM31::ONE,
        c1: QM31::ZERO,
    }

